import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Getting started","description":"Import your own subscription or mihomo YAML into Clash on iPhone or iPad, choose a node, and connect in three steps.","frontmatter":{"title":"Getting started","description":"Import your own subscription or mihomo YAML into Clash on iPhone or iPad, choose a node, and connect in three steps.","keywords":["Clash iOS guide","import Clash subscription on iPhone","import mihomo YAML","Clash node latency test","Clash Rule mode"],"jsonLd":{"@context":"https://schema.org","@type":"HowTo","name":"How to use Clash on iPhone or iPad","description":"Import your own subscription or configuration, choose a node, and connect.","inLanguage":"en-US","supply":[{"@type":"HowToSupply","name":"A working proxy server configuration or subscription URL"}],"step":[{"@type":"HowToStep","position":1,"name":"Import","text":"Add an HTTPS subscription URL, scan its QR code, open a YAML file, or import YAML through the system share sheet.","url":"https://clash.md/guide/#_1-import"},{"@type":"HowToStep","position":2,"name":"Pick a node","text":"Test latency, sort by delay, and choose the node you want to use.","url":"https://clash.md/guide/#_2-pick-a-node"},{"@type":"HowToStep","position":3,"name":"Connect","text":"Connect from the Home switch, Control Center, or Shortcuts.","url":"https://clash.md/guide/#_3-connect"}]}},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":0}`),a={name:`guide/index.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><p>Clash is a rule-based proxy utility powered by Hako. Import your own configuration or subscription, and Clash applies a direct, proxy, or blocking policy to each connection.</p><div class="tip custom-block"><p class="custom-block-title">Use your own configuration</p><p>Import a server configuration or subscription you choose and trust, then use Clash for testing, route selection, and rule-based traffic handling.</p></div><h2 id="_1-import" tabindex="-1">1. Import <a class="header-anchor" href="#_1-import" aria-label="Permalink to “1. Import”">​</a></h2><p>Add an HTTPS subscription URL, scan a QR code containing one, open a YAML file, or share a YAML configuration from another app.</p><p>Profiles may include credentials, so treat configuration files and backups as sensitive.</p><h2 id="_2-pick-a-node" tabindex="-1">2. Pick a node <a class="header-anchor" href="#_2-pick-a-node" aria-label="Permalink to “2. Pick a node”">​</a></h2><p>Test latency, sort by delay, and tap to switch.</p><h2 id="_3-connect" tabindex="-1">3. Connect <a class="header-anchor" href="#_3-connect" aria-label="Permalink to “3. Connect”">​</a></h2><p>Use the switch on Home, Control Center, or Shortcuts.</p><h2 id="compatibility-at-a-glance" tabindex="-1">Compatibility at a glance <a class="header-anchor" href="#compatibility-at-a-glance" aria-label="Permalink to “Compatibility at a glance”">​</a></h2><p>Clash reads mihomo-format YAML configurations and HTTPS subscriptions that return mihomo YAML. For a node supplied as an <code>ss://</code> link or in a Base64 node list, convert it to mihomo YAML or recreate it from its parameters in the node editor.</p><p>Standard Clash / mihomo YAML used by Stash imports directly. Nodes from sing-box, Surge, Quantumult X, Shadowrocket, and Loon can be reused through a mihomo subscription or recreated from their parameters in the node editor.</p><p>Read the <a href="/clash.md/guide/compatibility">complete compatibility guide</a> for exact compatibility details and dedicated pages for mihomo clients, sing-box, Surge, Quantumult X, Shadowrocket, Stash and Loon.</p><h2 id="supported-protocols" tabindex="-1">Supported protocols <a class="header-anchor" href="#supported-protocols" aria-label="Permalink to “Supported protocols”">​</a></h2><p>Clash currently supports 21 outbound protocol families, from HTTP, SOCKS, Shadowsocks, VMess, VLESS and Trojan to Hysteria2, TUIC, WireGuard, MASQUE, TrustTunnel and OpenVPN.</p><p>See the <a href="/clash.md/guide/protocols">supported protocol list</a> for every protocol and the available configuration methods.</p><h2 id="privacy-by-default" tabindex="-1">Privacy by default <a class="header-anchor" href="#privacy-by-default" aria-label="Permalink to “Privacy by default”">​</a></h2><p>Clash uses an account-free, local-first architecture. Profiles and operational data stay on your device, while network requests happen through features you configure or start.</p><p>Read the <a href="/clash.md/privacy">Privacy Policy</a> for the complete data-handling explanation.</p><h2 id="community-support" tabindex="-1">Community support <a class="header-anchor" href="#community-support" aria-label="Permalink to “Community support”">​</a></h2><p>Join the discussion in the <a href="https://github.com/TokenPLS/Hako-Client/issues" target="_blank" rel="noreferrer">Clash client issue tracker</a>. Use redacted subscription examples, server addresses, credentials, and logs in public issues.</p>`,22)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};